def search_google_scholar_key_words(query, num_results=None, locale=None, api_key=None, **_extra):
    import json, os, datetime, time, re, hashlib, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0513000" if __import__("os").path.isdir("./environment_mix/0513000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    # --- validation ---
    if not isinstance(query, str) or not query.strip():
        return _err("VALIDATION_ERROR", "query must be a non-empty string", field="query")
    q = query.strip()

    if num_results is None:
        num_results = 10
    if not isinstance(num_results, int):
        return _err("VALIDATION_ERROR", "num_results must be an integer", field="num_results")
    if num_results < 1 or num_results > 200:
        return _err("VALIDATION_ERROR", "num_results must be between 1 and 200", field="num_results")

    if locale is None:
        locale = "en"
    if not isinstance(locale, str) or not locale.strip():
        return _err("VALIDATION_ERROR", "locale must be a non-empty string", field="locale")
    locale = locale.strip()
    if len(locale) > 32 or not re.fullmatch(r"[A-Za-z]{2,3}([_-][A-Za-z]{2,4})?", locale):
        return _err("VALIDATION_ERROR", "locale must look like 'en' or 'en-US'", field="locale")

    if api_key is not None and not isinstance(api_key, str):
        return _err("VALIDATION_ERROR", "api_key must be a string", field="api_key")

    # --- load data ---
    api_keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")
    papers = _load("papers.json")
    search_results = _load("search_results.json")

    # --- resolve / authenticate key (if provided; otherwise run unkeyed) ---
    key_row = None
    api_key_id = None
    if api_key is not None:
        token = api_key.strip()
        if not token:
            return _err("UNAUTHORIZED", "api_key is empty")
        token_hash = hashlib.sha256(token.encode("utf-8")).hexdigest()
        # accept either id or the client-visible token value (by matching its hash)
        for r in api_keys:
            if r.get("id") == token or r.get("key_hash") == token_hash:
                key_row = r
                break
        if not key_row:
            return _err("UNAUTHORIZED", "api_key is invalid")
        if key_row.get("status") != "active":
            return _err("UNAUTHORIZED", "api_key is not active")
        api_key_id = key_row.get("id")

        # rolling daily reset
        try:
            reset_at = datetime.datetime.fromisoformat(key_row.get("quota_reset_at"))
        except Exception:
            return _err("VALIDATION_ERROR", "api_key quota_reset_at is invalid in datastore", api_key_id=api_key_id)
        if reset_at.tzinfo is None:
            reset_at = reset_at.replace(tzinfo=datetime.timezone.utc)
        if now >= reset_at:
            key_row["daily_requests_used"] = 0
            key_row["quota_reset_at"] = (now + datetime.timedelta(days=1)).isoformat()

        # quota
        dq = key_row.get("daily_request_quota")
        du = key_row.get("daily_requests_used")
        if not isinstance(dq, int) or dq < 0 or dq > 1000000:
            return _err("VALIDATION_ERROR", "api_key daily_request_quota invalid in datastore", api_key_id=api_key_id)
        if not isinstance(du, int) or du < 0:
            return _err("VALIDATION_ERROR", "api_key daily_requests_used invalid in datastore", api_key_id=api_key_id)
        if du >= dq:
            return _err("QUOTA_EXCEEDED", "daily request quota exceeded", api_key_id=api_key_id, daily_request_quota=dq)

        # rate limit per minute (count calls in last 60s for this api key via search_requests created_at)
        rl = key_row.get("rate_limit_per_minute")
        if not isinstance(rl, int) or rl < 1 or rl > 600:
            return _err("VALIDATION_ERROR", "api_key rate_limit_per_minute invalid in datastore", api_key_id=api_key_id)
        window_start = now - datetime.timedelta(seconds=60)
        recent = 0
        for req in search_requests:
            if req.get("api_key_id") != api_key_id:
                continue
            try:
                ca = datetime.datetime.fromisoformat(req.get("created_at"))
            except Exception:
                continue
            if ca.tzinfo is None:
                ca = ca.replace(tzinfo=datetime.timezone.utc)
            if ca >= window_start:
                recent += 1
        if recent >= rl:
            return _err("RATE_LIMIT", "rate limit exceeded", api_key_id=api_key_id, rate_limit_per_minute=rl)

    # --- create search request row (queued -> running -> succeeded) ---
    req_id = "sr_" + uuid.uuid4().hex
    req_row = {
        "id": req_id,
        "api_key_id": api_key_id,
        "tool_name": "search_google_scholar_key_words",
        "raw_parameters": {"query": query, "num_results": num_results, "locale": locale, "api_key": api_key},
        "query_text": q,
        "advanced_criteria": None,
        "locale": locale,
        "num_results_requested": num_results,
        "status": "queued",
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "result_count": 0,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    search_requests.append(req_row)

    # transition to running
    req_row["status"] = "running"
    req_row["started_at"] = now_iso
    req_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()

    # Simulated offline "fetch": create 0..N results deterministically from query
    # (Real backend would scrape Scholar; offline service persists normalized rows.)
    seed = int(hashlib.sha256((q + "|" + locale).encode("utf-8")).hexdigest()[:8], 16)
    # choose a stable count between 1 and num_results, but allow 0 for certain sparse queries
    if len(q) < 3:
        count = 0
    else:
        count = 1 + (seed % num_results)
        if "nonsense" in q.lower():
            count = 0

    created_papers = []
    created_results = []
    try:
        for i in range(count):
            rank = i + 1
            cluster_id = "cl_" + hashlib.sha1((q + f"|{locale}|{rank}").encode("utf-8")).hexdigest()[:16]
            title = f"{q} — Scholar result {rank}"
            venue = "Google Scholar (offline snapshot)"
            year = 2000 + ((seed + rank) % 25)
            snippet = f"Offline snapshot for query '{q}' (locale {locale})."
            citation_count = (seed + rank * 7) % 500

            pdf_url = None
            if (seed + rank) % 3 == 0:
                pdf_url = f"https://example.invalid/{cluster_id}.pdf"
            landing_url = f"https://scholar.google.com/scholar?cluster={cluster_id}&hl={locale}"

            # dedupe papers by scholar_cluster_id
            existing = None
            for p in papers:
                if p.get("scholar_cluster_id") == cluster_id:
                    existing = p
                    break
            if existing:
                existing["title"] = title
                existing["publication_venue"] = venue
                existing["publication_year"] = year
                existing["snippet"] = snippet
                existing["citation_count"] = int(citation_count)
                existing["pdf_url"] = pdf_url
                existing["landing_url"] = landing_url
                existing["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
                paper_row = existing
            else:
                paper_id = "pp_" + uuid.uuid4().hex
                paper_row = {
                    "id": paper_id,
                    "scholar_cluster_id": cluster_id,
                    "title": title,
                    "publication_venue": venue,
                    "publication_year": int(year),
                    "snippet": snippet,
                    "citation_count": int(citation_count),
                    "pdf_url": pdf_url,
                    "landing_url": landing_url,
                    "created_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
                    "updated_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
                }
                papers.append(paper_row)
            created_papers.append(paper_row)

            # enforce uniqueness on (search_request_id, rank) and (search_request_id, paper_id)
            for sr in search_results:
                if sr.get("search_request_id") == req_id and (sr.get("rank") == rank or sr.get("paper_id") == paper_row.get("id")):
                    # treat as conflict inside our own generated set: fail request
                    raise ValueError("duplicate search_results uniqueness violation")

            sr_row = {
                "id": "res_" + uuid.uuid4().hex,
                "search_request_id": req_id,
                "rank": int(rank),
                "paper_id": paper_row.get("id"),
                "result_source_url": landing_url,
                "raw_result": {
                    "title": title,
                    "cluster_id": cluster_id,
                    "venue": venue,
                    "year": year,
                    "citations": citation_count,
                    "snippet": snippet,
                    "pdf_url": pdf_url,
                    "landing_url": landing_url,
                },
                "created_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
                "updated_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
            }
            search_results.append(sr_row)
            created_results.append(sr_row)

        # finalize request
        finished = datetime.datetime.now(datetime.timezone.utc)
        req_row["status"] = "succeeded"
        req_row["finished_at"] = finished.isoformat()
        req_row["updated_at"] = finished.isoformat()
        # result_count must equal count(search_results where search_request_id=id)
        rc = sum(1 for r in search_results if r.get("search_request_id") == req_id)
        req_row["result_count"] = int(rc)

        # enforce finished_at rules
        try:
            started = datetime.datetime.fromisoformat(req_row["started_at"])
            if started.tzinfo is None:
                started = started.replace(tzinfo=datetime.timezone.utc)
            if finished < started:
                req_row["finished_at"] = started.isoformat()
                req_row["updated_at"] = req_row["finished_at"]
        except Exception:
            pass

        # update api key usage only after success persistence decision
        if key_row is not None:
            key_row["daily_requests_used"] = int(key_row.get("daily_requests_used", 0)) + 1
            key_row["last_used_at"] = now_iso
            key_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()

        _save("papers.json", papers)
        _save("search_results.json", search_results)
        _save("search_requests.json", search_requests)
        if key_row is not None:
            _save("api_keys.json", api_keys)

        # return persisted snapshot
        # include joined paper objects for convenience
        paper_by_id = {p["id"]: p for p in papers if isinstance(p, dict) and "id" in p}
        items = []
        for r in sorted((x for x in search_results if x.get("search_request_id") == req_id), key=lambda x: x.get("rank", 10**9)):
            pr = paper_by_id.get(r.get("paper_id"))
            items.append({"rank": r.get("rank"), "paper": pr, "search_result": r})

        return {
            "search_request": req_row,
            "results": items,
            "meta": {
                "latency_ms": int((time.time() - t0) * 1000),
                "num_results_requested": num_results,
                "num_results_returned": len(items),
            },
        }

    except ValueError as e:
        # mark failed request and persist
        finished = datetime.datetime.now(datetime.timezone.utc).isoformat()
        req_row["status"] = "failed"
        req_row["error_code"] = "PARSE_ERROR"
        req_row["error_message"] = str(e)
        req_row["finished_at"] = finished
        req_row["updated_at"] = finished
        req_row["result_count"] = 0
        _save("search_requests.json", search_requests)
        return _err("CONFLICT", "failed to persist results due to uniqueness conflict", search_request_id=req_id)
    except Exception:
        # unexpected - do not raise; store failed state
        finished = datetime.datetime.now(datetime.timezone.utc).isoformat()
        req_row["status"] = "failed"
        req_row["error_code"] = "INTERNAL_ERROR"
        req_row["error_message"] = "Unexpected error"
        req_row["finished_at"] = finished
        req_row["updated_at"] = finished
        req_row["result_count"] = 0
        _save("search_requests.json", search_requests)
        return _err("CONFLICT", "search execution failed unexpectedly", search_request_id=req_id)

def search_google_scholar_advanced(criteria, num_results=None, locale=None, api_key=None, **_extra):
    import json, os, datetime, time, re, uuid, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0513000" if __import__("os").path.isdir("./environment_mix/0513000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    # -------- validation --------
    if not isinstance(criteria, dict):
        return _err("VALIDATION_ERROR", "criteria must be an object", field="criteria")
    # Criteria is allowed to be empty per observed calls; infer/leave advanced_criteria empty.
    if num_results is None:
        num_results = 10
    if not isinstance(num_results, int):
        return _err("VALIDATION_ERROR", "num_results must be an integer", field="num_results")
    if num_results < 1 or num_results > 200:
        return _err("VALIDATION_ERROR", "num_results must be between 1 and 200", field="num_results")

    if locale is None:
        locale = "en"
    if not isinstance(locale, str) or not locale.strip():
        return _err("VALIDATION_ERROR", "locale must be a non-empty string", field="locale")
    locale = locale.strip()
    if len(locale) > 32 or not re.fullmatch(r"[A-Za-z]{2,3}([_-][A-Za-z]{2,4})?", locale):
        return _err("VALIDATION_ERROR", "locale must look like 'en' or 'en-US'", field="locale")

    if api_key is not None and (not isinstance(api_key, str) or not api_key.strip()):
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string when provided", field="api_key")

    # -------- load datastore --------
    api_keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")
    papers = _load("papers.json")
    search_results = _load("search_results.json")

    # -------- auth / choose working key context --------
    # IMPORTANT: never authenticate against key_hash (caller does not have plaintext for hashes stored).
    key_row = None
    api_key_id = None
    if api_key is not None:
        token = api_key.strip()
        for r in api_keys:
            if r.get("id") == token or r.get("key_prefix") == token:
                if r.get("status") == "active":
                    key_row = r
                    api_key_id = r.get("id")
                    break
        if not key_row:
            return _err("UNAUTHORIZED", "Invalid or inactive API key")
    else:
        # Ambient auth: pick any active key that can serve this request (quota/rate limit permitting).
        for r in api_keys:
            if r.get("status") == "active":
                key_row = r
                api_key_id = r.get("id")
                break
        # If no active key exists, run unkeyed mode (allowed by schema: api_key_id nullable).
        if not key_row:
            api_key_id = None

    # -------- quota / rate limit enforcement (only when keyed) --------
    # Uses api_keys.daily_requests_used/quota_reset_at and search_requests history for per-minute limiting.
    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    if key_row is not None:
        reset_dt = _parse_dt(key_row.get("quota_reset_at"))
        if reset_dt is None:
            return _err("UNAUTHORIZED", "API key quota configuration is invalid (quota_reset_at)")
        # reset if passed
        if now_dt >= reset_dt:
            key_row["daily_requests_used"] = 0
            key_row["quota_reset_at"] = (now_dt + datetime.timedelta(days=1)).replace(microsecond=0).isoformat().replace("+00:00", "Z")
            key_row["updated_at"] = now_iso

        daily_quota = key_row.get("daily_request_quota")
        used = key_row.get("daily_requests_used")
        if not isinstance(daily_quota, int) or daily_quota < 0:
            return _err("UNAUTHORIZED", "API key quota configuration is invalid (daily_request_quota)")
        if not isinstance(used, int) or used < 0:
            return _err("UNAUTHORIZED", "API key quota configuration is invalid (daily_requests_used)")
        if used >= daily_quota:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded", daily_request_quota=daily_quota, daily_requests_used=used)

        rl = key_row.get("rate_limit_per_minute")
        if not isinstance(rl, int) or rl < 1 or rl > 600:
            return _err("UNAUTHORIZED", "API key rate limit configuration is invalid (rate_limit_per_minute)")
        window_start = now_dt - datetime.timedelta(seconds=60)
        recent = 0
        for sr in search_requests:
            if sr.get("api_key_id") != api_key_id:
                continue
            cdt = _parse_dt(sr.get("created_at"))
            if cdt is None:
                continue
            if cdt >= window_start:
                recent += 1
        if recent >= rl:
            return _err("RATE_LIMIT", "Per-minute rate limit exceeded", rate_limit_per_minute=rl)

    # -------- create search_request row --------
    def _new_id(prefix):
        # stable unique-ish id format: <prefix>_<hex>
        return f"{prefix}_{uuid.uuid4().hex[:26]}"

    sreq_id = _new_id("gsch_sreq")
    started_at = now_iso
    req_row = {
        "id": sreq_id,
        "api_key_id": api_key_id,
        "tool_name": "search_google_scholar_advanced",
        "raw_parameters": {"criteria": criteria, "num_results": num_results, "locale": locale},
        "query_text": None,
        "advanced_criteria": criteria if criteria else {},
        "locale": locale,
        "num_results_requested": num_results,
        "status": "running",
        "error_code": None,
        "error_message": None,
        "started_at": started_at,
        "finished_at": None,
        "result_count": 0,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    search_requests.append(req_row)

    # update key usage metadata and counters (keyed only) AFTER passing checks and persisting request
    if key_row is not None:
        key_row["daily_requests_used"] = int(key_row.get("daily_requests_used", 0)) + 1
        key_row["last_used_at"] = now_iso
        key_row["updated_at"] = now_iso

    # persist request + key counter changes early (observable dynamics)
    _save("search_requests.json", search_requests)
    if key_row is not None:
        _save("api_keys.json", api_keys)

    # -------- execute (offline): synthesize deterministic placeholder results from criteria --------
    # This server runs offline; we persist a snapshot that behaves like a completed run.
    try:
        # derive seed text to make results stable for same criteria
        crit_text = json.dumps(criteria, sort_keys=True, ensure_ascii=False)
    except Exception:
        crit_text = str(criteria)

    base_seed = hashlib.sha256((crit_text + "|" + locale).encode("utf-8")).hexdigest()

    def _paper_id():
        return f"gsch_pap_{uuid.uuid4().hex[:26]}"

    def _sres_id():
        return f"gsch_sres_{uuid.uuid4().hex[:26]}"

    def _dedup_upsert_paper(paper):
        # Deduplicate by scholar_cluster_id if present; update existing row rather than insert duplicate.
        cluster_id = paper.get("scholar_cluster_id")
        existing = None
        if cluster_id:
            for p in papers:
                if p.get("scholar_cluster_id") == cluster_id:
                    existing = p
                    break
        if existing is not None:
            # update fields
            for f in ("title", "publication_venue", "publication_year", "snippet", "citation_count", "pdf_url", "landing_url"):
                if paper.get(f) is not None:
                    existing[f] = paper.get(f)
            existing["updated_at"] = now_iso
            return existing["id"]
        else:
            papers.append(paper)
            return paper["id"]

    results_created = 0
    created_sres_rows = []
    for i in range(1, num_results + 1):
        # keep it lightweight: create as many as requested, capped by num_results
        # include scholar_cluster_id for dedup opportunity
        cluster_id = "c_" + base_seed[i:i+16]
        title = f"Scholar result {i} ({locale})"
        venue = None
        year = None
        snippet = f"Offline snapshot generated for criteria hash {base_seed[:12]}."
        citation_count = int(base_seed[i:i+2], 16) % 500

        paper_row = {
            "id": _paper_id(),
            "scholar_cluster_id": cluster_id,
            "title": title,
            "publication_venue": venue,
            "publication_year": year,
            "snippet": snippet,
            "citation_count": citation_count,
            "pdf_url": None,
            "landing_url": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        paper_id = _dedup_upsert_paper(paper_row)

        sres_row = {
            "id": _sres_id(),
            "search_request_id": sreq_id,
            "rank": i,
            "paper_id": paper_id,
            "result_source_url": None,
            "raw_result": {
                "title": title,
                "cluster_id": cluster_id,
                "citation_count": citation_count,
                "locale": locale,
            },
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        # enforce unique(search_request_id, rank) and unique(search_request_id, paper_id)
        # since we're generating, avoid duplicates by construction; still guard
        if any(r.get("search_request_id") == sreq_id and r.get("rank") == i for r in search_results):
            continue
        if any(r.get("search_request_id") == sreq_id and r.get("paper_id") == paper_id for r in search_results):
            continue

        search_results.append(sres_row)
        created_sres_rows.append(sres_row)
        results_created += 1

    # finalize request row: running -> succeeded, finished_at non-null, result_count consistent
    finished_at = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    req_row["status"] = "succeeded"
    req_row["finished_at"] = finished_at
    req_row["result_count"] = results_created
    req_row["updated_at"] = finished_at

    # persist all
    _save("papers.json", papers)
    _save("search_results.json", search_results)
    _save("search_requests.json", search_requests)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "search_request": req_row,
        "results": sorted(created_sres_rows, key=lambda r: r.get("rank", 0)),
        "meta": {"latency_ms": latency_ms},
    }

def get_author_info(author_id, locale=None, api_key=None, refresh=None, **_extra):
    import json, os, datetime, time, re, hashlib, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0513000" if __import__("os").path.isdir("./environment_mix/0513000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    if not isinstance(author_id, str) or not author_id.strip():
        return _err("VALIDATION_ERROR", "author_id must be a non-empty string", field="author_id")
    scholar_author_id = author_id.strip()
    if len(scholar_author_id) > 128 or not re.fullmatch(r"[A-Za-z0-9_-]+", scholar_author_id):
        return _err("VALIDATION_ERROR", "author_id is malformed", field="author_id")

    if locale is None:
        locale = "en"
    if not isinstance(locale, str) or not locale.strip():
        return _err("VALIDATION_ERROR", "locale must be a non-empty string", field="locale")
    locale = locale.strip()
    if len(locale) > 32 or not re.fullmatch(r"[A-Za-z]{2,3}([_-][A-Za-z]{2,4})?", locale):
        return _err("VALIDATION_ERROR", "locale must look like 'en' or 'en-US'", field="locale")

    if refresh is None:
        refresh = False
    if not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean", field="refresh")

    if api_key is None or not isinstance(api_key, str) or not api_key.strip():
        return _err("UNAUTHORIZED", "api_key is required")

    api_keys = _load("api_keys.json")
    authors = _load("authors.json")
    search_requests = _load("search_requests.json")  # used for rate limiting window counts

    token = api_key.strip()
    token_hash = hashlib.sha256(token.encode("utf-8")).hexdigest()
    key_row = None
    for r in api_keys:
        if r.get("id") == token or r.get("key_hash") == token_hash:
            key_row = r
            break
    if not key_row:
        return _err("UNAUTHORIZED", "api_key is invalid")
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "api_key is not active")
    api_key_id = key_row.get("id")

    # rolling daily reset
    try:
        reset_at = datetime.datetime.fromisoformat(key_row.get("quota_reset_at"))
    except Exception:
        return _err("VALIDATION_ERROR", "api_key quota_reset_at is invalid in datastore", api_key_id=api_key_id)
    if reset_at.tzinfo is None:
        reset_at = reset_at.replace(tzinfo=datetime.timezone.utc)
    if now >= reset_at:
        key_row["daily_requests_used"] = 0
        key_row["quota_reset_at"] = (now + datetime.timedelta(days=1)).isoformat()

    dq = key_row.get("daily_request_quota")
    du = key_row.get("daily_requests_used")
    if not isinstance(dq, int) or dq < 0 or dq > 1000000:
        return _err("VALIDATION_ERROR", "api_key daily_request_quota invalid in datastore", api_key_id=api_key_id)
    if not isinstance(du, int) or du < 0:
        return _err("VALIDATION_ERROR", "api_key daily_requests_used invalid in datastore", api_key_id=api_key_id)
    if du >= dq:
        return _err("QUOTA_EXCEEDED", "daily request quota exceeded", api_key_id=api_key_id, daily_request_quota=dq)

    rl = key_row.get("rate_limit_per_minute")
    if not isinstance(rl, int) or rl < 1 or rl > 600:
        return _err("VALIDATION_ERROR", "api_key rate_limit_per_minute invalid in datastore", api_key_id=api_key_id)
    window_start = now - datetime.timedelta(seconds=60)
    recent = 0
    for req in search_requests:
        if req.get("api_key_id") != api_key_id:
            continue
        try:
            ca = datetime.datetime.fromisoformat(req.get("created_at"))
        except Exception:
            continue
        if ca.tzinfo is None:
            ca = ca.replace(tzinfo=datetime.timezone.utc)
        if ca >= window_start:
            recent += 1
    if recent >= rl:
        return _err("RATE_LIMIT", "rate limit exceeded", api_key_id=api_key_id, rate_limit_per_minute=rl)

    # find existing author
    existing = None
    for a in authors:
        if a.get("scholar_author_id") == scholar_author_id:
            existing = a
            break

    # if exists and no refresh requested, return existing
    if existing and not refresh:
        # update api key usage (counts as request)
        key_row["daily_requests_used"] = int(key_row.get("daily_requests_used", 0)) + 1
        key_row["last_used_at"] = now_iso
        key_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        _save("api_keys.json", api_keys)
        return {
            "author": existing,
            "meta": {"latency_ms": int((time.time() - t0) * 1000), "refreshed": False},
        }

    # offline "fetch" simulation; unreachable/blocked path
    blocked = scholar_author_id.lower().startswith("blocked") or scholar_author_id.lower().endswith("blocked")

    if blocked:
        # must not corrupt existing author data; may mark stale; record failure (not modeled)
        if existing:
            # legal transition: active->stale or stale->stale allowed by staying; disabled cannot transition
            if existing.get("status") == "disabled":
                # cannot change; still return stale-ish failure
                key_row["daily_requests_used"] = int(key_row.get("daily_requests_used", 0)) + 1
                key_row["last_used_at"] = now_iso
                key_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
                _save("api_keys.json", api_keys)
                return _err("NOT_FOUND", "author profile unreachable", scholar_author_id=scholar_author_id)
            existing["status"] = "stale"
            existing["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
            _save("authors.json", authors)
            key_row["daily_requests_used"] = int(key_row.get("daily_requests_used", 0)) + 1
            key_row["last_used_at"] = now_iso
            key_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
            _save("api_keys.json", api_keys)
            return _err("NOT_FOUND", "author profile unreachable", scholar_author_id=scholar_author_id)
        return _err("NOT_FOUND", "author profile not found", scholar_author_id=scholar_author_id)

    # "fetch" successful: upsert fields
    seed = int(hashlib.sha256((scholar_author_id + "|" + locale).encode("utf-8")).hexdigest()[:8], 16)
    name = f"Author {scholar_author_id}"
    affiliation = f"Affiliation {((seed % 50) + 1)}"
    email_domain = None if seed % 5 == 0 else f"university{seed%100}.edu"
    interests = [f"interest_{(seed+i)%20}" for i in range((seed % 5) + 1)]
    homepage_url = None if seed % 4 == 0 else f"https://example.invalid/~{scholar_author_id}"
    cited_by = seed % 50000
    h_index = min(200, (seed % 80))
    i10_index = min(500, (seed % 200))

    if existing:
        if existing.get("status") == "disabled":
            return _err("INVALID_TRANSITION", "author profile is disabled and cannot be refreshed", scholar_author_id=scholar_author_id)
        existing["name"] = name
        existing["affiliation"] = affiliation
        existing["email_domain"] = email_domain
        existing["interests"] = interests
        existing["homepage_url"] = homepage_url
        existing["cited_by"] = int(cited_by)
        existing["h_index"] = int(h_index)
        existing["i10_index"] = int(i10_index)
        existing["profile_last_fetched_at"] = now_iso
        existing["status"] = "active"
        existing["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        author_row = existing
    else:
        author_row = {
            "id": "au_" + uuid.uuid4().hex,
            "scholar_author_id": scholar_author_id,
            "name": name,
            "affiliation": affiliation,
            "email_domain": email_domain,
            "interests": interests,
            "homepage_url": homepage_url,
            "cited_by": int(cited_by),
            "h_index": int(h_index),
            "i10_index": int(i10_index),
            "profile_last_fetched_at": now_iso,
            "status": "active",
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        # uniqueness check scholar_author_id
        for a in authors:
            if a.get("scholar_author_id") == scholar_author_id:
                return _err("CONFLICT", "author already exists with this scholar_author_id", scholar_author_id=scholar_author_id)
        authors.append(author_row)

    # persist
    _save("authors.json", authors)

    key_row["daily_requests_used"] = int(key_row.get("daily_requests_used", 0)) + 1
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    _save("api_keys.json", api_keys)

    return {
        "author": author_row,
        "meta": {"latency_ms": int((time.time() - t0) * 1000), "refreshed": True},
    }

def list_search_requests(api_key, status=None, tool_name=None, query_contains=None, created_after=None, created_before=None, page=None, page_size=None, **_extra):
    import json, os, datetime, time, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0513000" if __import__("os").path.isdir("./environment_mix/0513000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    if api_key is None or not isinstance(api_key, str) or not api_key.strip():
        return _err("UNAUTHORIZED", "api_key is required")
    if status is not None and status not in ("queued", "running", "succeeded", "failed", "cancelled"):
        return _err("VALIDATION_ERROR", "invalid status", field="status")
    if tool_name is not None and tool_name not in ("search_google_scholar_key_words", "search_google_scholar_advanced"):
        return _err("VALIDATION_ERROR", "invalid tool_name", field="tool_name")
    if query_contains is not None and not isinstance(query_contains, str):
        return _err("VALIDATION_ERROR", "query_contains must be a string", field="query_contains")

    def _parse_rfc3339(s, field):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return _err("VALIDATION_ERROR", f"{field} must be an RFC3339 timestamp", field=field)
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return _err("VALIDATION_ERROR", f"{field} must be an RFC3339 timestamp", field=field)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt

    ca = _parse_rfc3339(created_after, "created_after")
    if isinstance(ca, dict) and "error" in ca:
        return ca
    cb = _parse_rfc3339(created_before, "created_before")
    if isinstance(cb, dict) and "error" in cb:
        return cb
    if ca and cb and cb < ca:
        return _err("VALIDATION_ERROR", "created_before must be >= created_after", field="created_before")

    if page is None:
        page = 1
    if page_size is None:
        page_size = 20
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1", field="page")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        return _err("VALIDATION_ERROR", "page_size must be between 1 and 100", field="page_size")

    api_keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")

    token = api_key.strip()
    token_hash = hashlib.sha256(token.encode("utf-8")).hexdigest()
    key_row = None
    for r in api_keys:
        if r.get("id") == token or r.get("key_hash") == token_hash:
            key_row = r
            break
    if not key_row:
        return _err("UNAUTHORIZED", "api_key is invalid")
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "api_key is not active")
    api_key_id = key_row.get("id")

    # rolling daily reset
    try:
        reset_at = datetime.datetime.fromisoformat(key_row.get("quota_reset_at"))
    except Exception:
        return _err("VALIDATION_ERROR", "api_key quota_reset_at is invalid in datastore", api_key_id=api_key_id)
    if reset_at.tzinfo is None:
        reset_at = reset_at.replace(tzinfo=datetime.timezone.utc)
    if now >= reset_at:
        key_row["daily_requests_used"] = 0
        key_row["quota_reset_at"] = (now + datetime.timedelta(days=1)).isoformat()

    dq = key_row.get("daily_request_quota")
    du = key_row.get("daily_requests_used")
    if not isinstance(dq, int) or dq < 0 or dq > 1000000:
        return _err("VALIDATION_ERROR", "api_key daily_request_quota invalid in datastore", api_key_id=api_key_id)
    if not isinstance(du, int) or du < 0:
        return _err("VALIDATION_ERROR", "api_key daily_requests_used invalid in datastore", api_key_id=api_key_id)
    if du >= dq:
        return _err("QUOTA_EXCEEDED", "daily request quota exceeded", api_key_id=api_key_id, daily_request_quota=dq)

    # per-minute rate limit for this key (count in last 60 seconds from search_requests created_at)
    rl = key_row.get("rate_limit_per_minute")
    if not isinstance(rl, int) or rl < 1 or rl > 600:
        return _err("VALIDATION_ERROR", "api_key rate_limit_per_minute invalid in datastore", api_key_id=api_key_id)
    window_start = now - datetime.timedelta(seconds=60)
    recent = 0
    for req in search_requests:
        if req.get("api_key_id") != api_key_id:
            continue
        try:
            dt = datetime.datetime.fromisoformat(req.get("created_at"))
        except Exception:
            continue
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        if dt >= window_start:
            recent += 1
    if recent >= rl:
        return _err("RATE_LIMIT", "rate limit exceeded", api_key_id=api_key_id, rate_limit_per_minute=rl)

    # filter to caller's requests
    rows = [r for r in search_requests if r.get("api_key_id") == api_key_id]

    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if tool_name is not None:
        rows = [r for r in rows if r.get("tool_name") == tool_name]
    if query_contains is not None:
        qc = query_contains.casefold()
        rows = [r for r in rows if isinstance(r.get("query_text"), str) and qc in r["query_text"].casefold()]
    if ca is not None:
        def _ge_created(r):
            try:
                dt = datetime.datetime.fromisoformat(r.get("created_at"))
            except Exception:
                return False
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt >= ca
        rows = [r for r in rows if _ge_created(r)]
    if cb is not None:
        def _lt_created(r):
            try:
                dt = datetime.datetime.fromisoformat(r.get("created_at"))
            except Exception:
                return False
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt < cb
        rows = [r for r in rows if _lt_created(r)]

    # order by created_at desc (invalid timestamps last)
    def _created_key(r):
        try:
            dt = datetime.datetime.fromisoformat(r.get("created_at"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

    rows.sort(key=_created_key, reverse=True)

    total = len(rows)
    start = (page - 1) * page_size
    end = start + page_size
    page_items = rows[start:end]
    has_more = end < total

    # usage counts as a request (read included)
    key_row["daily_requests_used"] = int(key_row.get("daily_requests_used", 0)) + 1
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    _save("api_keys.json", api_keys)

    return {
        "data": page_items,
        "meta": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }

def get_search_request(api_key, search_request_id, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0513000" if __import__("os").path.isdir("./environment_mix/0513000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string", field="api_key")
    if not isinstance(search_request_id, str) or not search_request_id.strip():
        return _err("VALIDATION_ERROR", "search_request_id must be a non-empty string", field="search_request_id")

    api_keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")

    ak = api_key.strip()
    key_row = None
    for r in api_keys:
        if r.get("id") == ak or r.get("key_prefix") == ak:
            if r.get("status") == "active":
                key_row = r
                break
    if not key_row:
        return _err("UNAUTHORIZED", "Invalid or inactive API key")

    # quota/rate-limits are enforced for reads too (schema includes counters); be permissive but real.
    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    reset_dt = _parse_dt(key_row.get("quota_reset_at"))
    if reset_dt is not None and now_dt >= reset_dt:
        key_row["daily_requests_used"] = 0
        key_row["quota_reset_at"] = (now_dt + datetime.timedelta(days=1)).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        key_row["updated_at"] = now_iso

    # Per-minute limit for reads as well: count search_requests created in last minute for this key.
    rl = key_row.get("rate_limit_per_minute")
    if isinstance(rl, int) and rl >= 1:
        window_start = now_dt - datetime.timedelta(seconds=60)
        recent = 0
        for sr in search_requests:
            if sr.get("api_key_id") != key_row.get("id"):
                continue
            cdt = _parse_dt(sr.get("created_at"))
            if cdt is not None and cdt >= window_start:
                recent += 1
        if recent >= rl:
            return _err("RATE_LIMIT", "Per-minute rate limit exceeded", rate_limit_per_minute=rl)

    # Update key last_used_at (observable dynamics)
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    sreq = None
    sid = search_request_id.strip()
    for r in search_requests:
        if r.get("id") == sid:
            sreq = r
            break
    if not sreq:
        return _err("NOT_FOUND", "Search request not found", search_request_id=sid)

    latency_ms = int((time.time() - t0) * 1000)
    return {"search_request": sreq, "meta": {"latency_ms": latency_ms}}

def cancel_search_request(api_key, search_request_id, reason=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0513000" if __import__("os").path.isdir("./environment_mix/0513000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except ValueError:
            return None

    def _as_list(x):
        return x if isinstance(x, list) else []

    def _rows(obj):
        # datastore files may be either a list of rows or {"rows":[...]}
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"]
        return _as_list(obj)

    def _writeback_shape(original, rows_list):
        if isinstance(original, dict) and "rows" in original and isinstance(original["rows"], list):
            new_obj = dict(original)
            new_obj["rows"] = rows_list
            return new_obj
        return rows_list

    def _quota_reset_if_needed(key_row, now_dt):
        # returns (changed:bool, error_obj_or_none)
        qra = key_row.get("quota_reset_at")
        qdt = _parse_dt(qra) if isinstance(qra, str) else None
        if qdt is None:
            return False, _err("VALIDATION_ERROR", "api_keys.quota_reset_at is invalid for this key", api_key_id=key_row.get("id"))
        # rolling daily reset
        if now_dt >= qdt:
            # advance by whole days until in the future
            while now_dt >= qdt:
                qdt = qdt + datetime.timedelta(days=1)
            key_row["daily_requests_used"] = 0
            key_row["quota_reset_at"] = _iso(qdt)
            return True, None
        return False, None

    def _enforce_rate_and_quota(api_key_row, api_key_id, now_dt):
        # For cancel, still counts as a request.
        changed, e = _quota_reset_if_needed(api_key_row, now_dt)
        if e:
            return None, e, changed

        rl = api_key_row.get("rate_limit_per_minute")
        if not isinstance(rl, int) or rl < 1 or rl > 600:
            return None, _err("VALIDATION_ERROR", "rate_limit_per_minute is invalid for this key", api_key_id=api_key_id), changed

        dq = api_key_row.get("daily_request_quota")
        used = api_key_row.get("daily_requests_used")
        if not isinstance(dq, int) or dq < 0 or dq > 1000000:
            return None, _err("VALIDATION_ERROR", "daily_request_quota is invalid for this key", api_key_id=api_key_id), changed
        if not isinstance(used, int) or used < 0:
            return None, _err("VALIDATION_ERROR", "daily_requests_used is invalid for this key", api_key_id=api_key_id), changed

        if dq == 0 or used >= dq:
            return None, _err("QUOTA_EXCEEDED", "Daily request quota exceeded for this API key", api_key_id=api_key_id), changed

        # rate limit: count prior requests in last 60s by this api_key_id
        reqlog_obj = _load("search_requests.json")
        reqlog_rows = _rows(reqlog_obj)
        cutoff = now_dt - datetime.timedelta(seconds=60)
        n_last_min = 0
        for r in reqlog_rows:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            ts = _parse_dt(r.get("created_at")) or _parse_dt(r.get("updated_at"))
            if ts is not None and ts >= cutoff:
                n_last_min += 1
        if n_last_min >= rl:
            return None, _err("RATE_LIMIT", "Per-minute rate limit exceeded for this API key", api_key_id=api_key_id, rate_limit_per_minute=rl), changed

        # consume
        api_key_row["daily_requests_used"] = used + 1
        api_key_row["last_used_at"] = _iso(now_dt)
        api_key_row["updated_at"] = _iso(now_dt)
        return api_key_row, None, True

    t0 = time.time()
    now_dt = _now()
    now_iso = _iso(now_dt)

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string", field="api_key")
    if not isinstance(search_request_id, str) or not search_request_id.strip():
        return _err("VALIDATION_ERROR", "search_request_id must be a non-empty string", field="search_request_id")
    if reason is not None and (not isinstance(reason, str) or len(reason) > 2000):
        return _err("VALIDATION_ERROR", "reason must be a string up to 2000 characters", field="reason")

    ak = api_key.strip()
    sreq_id = search_request_id.strip()

    # Load collections (preserve original shapes for save)
    api_keys_obj = _load("api_keys.json")
    search_requests_obj = _load("search_requests.json")
    search_results_obj = _load("search_results.json")

    api_keys_rows = _rows(api_keys_obj)
    search_requests_rows = _rows(search_requests_obj)
    search_results_rows = _rows(search_results_obj)

    # Authenticate against client-visible value: id OR key_prefix. NEVER against key_hash.
    key_row = None
    for r in api_keys_rows:
        if not isinstance(r, dict):
            continue
        if r.get("id") == ak or r.get("key_prefix") == ak:
            key_row = r
            break
    if not key_row or key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "Invalid or inactive API key (must match api_keys.id or api_keys.key_prefix and be status='active')")

    api_key_id = key_row.get("id")

    # Enforce quota/rate limit for this call (service dynamics).
    key_row_after, quota_err, key_changed = _enforce_rate_and_quota(key_row, api_key_id, now_dt)
    if quota_err:
        # Must not persist a cancellation attempt when auth/quota fails.
        return quota_err

    # Find target search_request
    sreq = None
    sreq_idx = None
    for i, r in enumerate(search_requests_rows):
        if isinstance(r, dict) and r.get("id") == sreq_id:
            sreq = r
            sreq_idx = i
            break
    if sreq is None:
        # persist API key usage changes only if we decided to count this call; real services do.
        if key_changed:
            _save("api_keys.json", _writeback_shape(api_keys_obj, api_keys_rows))
        return _err("NOT_FOUND", "search_request_id does not exist", search_request_id=sreq_id)

    # Authorization: if request has api_key_id, it must match provided key.
    req_key_id = sreq.get("api_key_id")
    if req_key_id is not None and req_key_id != api_key_id:
        if key_changed:
            _save("api_keys.json", _writeback_shape(api_keys_obj, api_keys_rows))
        return _err("UNAUTHORIZED", "API key is not authorized to cancel this search request", search_request_id=sreq_id)

    # Transition rules
    status = sreq.get("status")
    if status in ("succeeded", "failed", "cancelled"):
        if key_changed:
            _save("api_keys.json", _writeback_shape(api_keys_obj, api_keys_rows))
        return _err("CONFLICT", "Search request is already in a terminal state and cannot be cancelled", status=status, search_request_id=sreq_id)
    if status not in ("queued", "running"):
        if key_changed:
            _save("api_keys.json", _writeback_shape(api_keys_obj, api_keys_rows))
        return _err("INVALID_TRANSITION", "Only queued or running search requests can be cancelled", from_status=status, to_status="cancelled", search_request_id=sreq_id)

    # Apply cancellation
    started_at_dt = _parse_dt(sreq.get("started_at"))
    finished_dt = now_dt
    if started_at_dt is not None and finished_dt < started_at_dt:
        finished_dt = started_at_dt  # enforce finished_at >= started_at

    sreq["status"] = "cancelled"
    sreq["error_code"] = "CANCELLED"
    if reason is not None and reason.strip():
        sreq["error_message"] = reason.strip()
    else:
        sreq["error_message"] = sreq.get("error_message")  # keep existing if any

    sreq["finished_at"] = _iso(finished_dt)
    sreq["updated_at"] = now_iso

    # Ensure finished_at null rule is satisfied (now non-null), and result_count consistent (count existing results)
    cnt = 0
    for rr in search_results_rows:
        if isinstance(rr, dict) and rr.get("search_request_id") == sreq_id:
            cnt += 1
    if not isinstance(sreq.get("result_count"), int) or sreq.get("result_count") != cnt:
        sreq["result_count"] = cnt

    # Persist mutations (API key counters + request row)
    search_requests_rows[sreq_idx] = sreq
    _save("api_keys.json", _writeback_shape(api_keys_obj, api_keys_rows))
    _save("search_requests.json", _writeback_shape(search_requests_obj, search_requests_rows))
    # search_results unchanged for cancel

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "search_request": sreq,
        "cancelled": True,
        "latency_ms": latency_ms
    }

def list_search_results(api_key, search_request_id, page=None, page_size=None, **_extra):
    import json, os, datetime, time, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0513000" if __import__("os").path.isdir("./environment_mix/0513000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string", field="api_key")
    if not isinstance(search_request_id, str) or not search_request_id.strip():
        return _err("VALIDATION_ERROR", "search_request_id must be a non-empty string", field="search_request_id")

    if page is None:
        page = 1
    if page_size is None:
        page_size = 25
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1", field="page")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 100", field="page_size")

    api_keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")
    search_results = _load("search_results.json")

    ak = api_key.strip()
    key_row = None
    for r in api_keys:
        if r.get("id") == ak or r.get("key_prefix") == ak:
            if r.get("status") == "active":
                key_row = r
                break
    if not key_row:
        return _err("UNAUTHORIZED", "Invalid or inactive API key")

    # rate-limit reads
    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    rl = key_row.get("rate_limit_per_minute")
    if isinstance(rl, int) and rl >= 1:
        window_start = now_dt - datetime.timedelta(seconds=60)
        recent = 0
        for sr in search_requests:
            if sr.get("api_key_id") != key_row.get("id"):
                continue
            cdt = _parse_dt(sr.get("created_at"))
            if cdt is not None and cdt >= window_start:
                recent += 1
        if recent >= rl:
            return _err("RATE_LIMIT", "Per-minute rate limit exceeded", rate_limit_per_minute=rl)

    # update key last_used_at
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    sid = search_request_id.strip()
    if not any(r.get("id") == sid for r in search_requests):
        return _err("NOT_FOUND", "Search request not found", search_request_id=sid)

    rows = [r for r in search_results if r.get("search_request_id") == sid]
    rows.sort(key=lambda r: r.get("rank", 0))

    total = len(rows)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = rows[start:end]
    has_more = end < total

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "data": page_rows,
        "meta": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
            "next_page": (page + 1) if has_more else None,
            "latency_ms": latency_ms,
        },
    }

def get_paper(api_key, paper_id, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0513000" if __import__("os").path.isdir("./environment_mix/0513000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    api_keys = _load("api_keys.json")
    papers = _load("papers.json")
    search_requests = _load("search_requests.json")  # for rate-limit window counting (calls)
    def _log(status, api_key_id=None):
        if api_key_id:
            for k in api_keys:
                if k.get("id") == api_key_id:
                    k["last_used_at"] = now
                    k["updated_at"] = now
                    break
            _save("api_keys.json", api_keys)
        return

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(paper_id, str) or not paper_id.strip():
        return _err("VALIDATION_ERROR", "paper_id must be a non-empty string")

    # Authenticate (id or key_prefix)
    key_row = None
    ak = api_key.strip()
    for k in api_keys:
        if k.get("id") == ak or k.get("key_prefix") == ak:
            key_row = k
            break
    if not key_row or key_row.get("status") != "active":
        _log("error", None)
        return _err("UNAUTHORIZED", "Invalid or inactive API key")

    # Enforce quota + rate limit (using search_requests as the only usage/audit-like collection available)
    try:
        reset_at = key_row.get("quota_reset_at")
        if not isinstance(reset_at, str) or not reset_at:
            _log("error", key_row.get("id"))
            return _err("UNAUTHORIZED", "API key quota configuration is invalid")
        reset_dt = datetime.datetime.fromisoformat(reset_at.replace("Z", "+00:00"))
        now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        if now_dt >= reset_dt:
            key_row["daily_requests_used"] = 0
            key_row["quota_reset_at"] = (now_dt + datetime.timedelta(days=1)).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    except Exception:
        _log("error", key_row.get("id"))
        return _err("UNAUTHORIZED", "API key quota configuration is invalid")

    daily_quota = key_row.get("daily_request_quota")
    used = key_row.get("daily_requests_used")
    if not isinstance(daily_quota, int) or not isinstance(used, int) or daily_quota < 0 or used < 0:
        _log("error", key_row.get("id"))
        return _err("UNAUTHORIZED", "API key quota configuration is invalid")
    if daily_quota == 0 or used >= daily_quota:
        _log("error", key_row.get("id"))
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")

    per_min = key_row.get("rate_limit_per_minute")
    if not isinstance(per_min, int) or per_min < 1 or per_min > 600:
        _log("error", key_row.get("id"))
        return _err("UNAUTHORIZED", "API key rate limit configuration is invalid")

    window_start = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0)
    cnt = 0
    for r in search_requests:
        if r.get("api_key_id") != key_row.get("id"):
            continue
        ca = r.get("created_at")
        if not isinstance(ca, str) or not ca:
            continue
        try:
            ca_dt = datetime.datetime.fromisoformat(ca.replace("Z", "+00:00"))
        except Exception:
            continue
        if ca_dt.tzinfo is None:
            ca_dt = ca_dt.replace(tzinfo=datetime.timezone.utc)
        if ca_dt >= window_start.replace(tzinfo=datetime.timezone.utc):
            cnt += 1
    if cnt >= per_min:
        _log("error", key_row.get("id"))
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # Charge usage for this call
    key_row["daily_requests_used"] = used + 1
    key_row["last_used_at"] = now
    key_row["updated_at"] = now
    _save("api_keys.json", api_keys)

    pid = paper_id.strip()
    paper = None
    for p in papers:
        if p.get("id") == pid:
            paper = p
            break

    if not paper:
        _log("error", key_row.get("id"))
        return _err("NOT_FOUND", "paper_id not found")

    _log("ok", key_row.get("id"))
    return {"paper": paper}

def get_current_identity(api_key, **_extra):
    import json, os, datetime, time, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0513000" if __import__("os").path.isdir("./environment_mix/0513000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_collection_file(filename):
        path = os.path.join(_DB, filename)
        if not os.path.exists(_DB):
            os.makedirs(_DB, exist_ok=True)
        if not os.path.exists(path):
            _save(filename, [])

    def _hash_candidate(token):
        # Stored is "key_hash" but the algorithm isn't specified.
        # Try a small set of common encodings deterministically.
        cands = []
        try:
            cands.append(hashlib.sha256(token.encode("utf-8")).hexdigest())
        except Exception:
            pass
        try:
            cands.append(hashlib.sha1(token.encode("utf-8")).hexdigest())
        except Exception:
            pass
        try:
            cands.append(hashlib.md5(token.encode("utf-8")).hexdigest())
        except Exception:
            pass
        return [c for c in cands if c]

    # Validate inputs
    if api_key is None or not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string.", field="api_key")

    t0 = time.time()

    # Ensure files exist
    _ensure_collection_file("api_keys.json")
    _ensure_collection_file("search_requests.json")

    keys = _load("api_keys.json")

    # Authenticate:
    # Must match by client-visible value or id. Since raw token isn't stored, accept:
    # - exact match to api_keys.id
    # - exact match to api_keys.key_prefix (some deployments treat it as the presented credential)
    # - if the presented key looks like a full token, attempt hashing and compare to key_hash
    key_row = None
    api_key_s = api_key.strip()

    # Prefer exact id match
    for r in keys:
        if isinstance(r, dict) and r.get("id") == api_key_s:
            key_row = r
            break

    # Then prefix match
    if key_row is None:
        for r in keys:
            if isinstance(r, dict) and r.get("key_prefix") == api_key_s:
                key_row = r
                break

    # Then hash match (best-effort; only works if store uses one of the attempted hashes)
    if key_row is None:
        hc = _hash_candidate(api_key_s)
        if hc:
            hset = set(hc)
            for r in keys:
                if isinstance(r, dict) and r.get("key_hash") in hset:
                    key_row = r
                    break

    # Prepare request log row helper (search_requests is the only request-log-like collection modeled)
    def _log_request(status, api_key_id=None, error_code=None, error_message=None):
        reqs = _load("search_requests.json")
        now = _now()
        rid = "sr_" + secrets.token_hex(12)
        row = {
            "id": rid,
            "api_key_id": api_key_id,
            "tool_name": "search_google_scholar_key_words",
            "raw_parameters": {"endpoint": "get_current_identity"},
            "query_text": None,
            "advanced_criteria": None,
            "locale": None,
            "num_results_requested": 1,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "started_at": now if status in ("running", "succeeded", "failed", "cancelled") else None,
            "finished_at": now if status in ("succeeded", "failed", "cancelled") else None,
            "result_count": 0,
            "created_at": now,
            "updated_at": now,
        }
        reqs.append(row)
        _save("search_requests.json", reqs)

    # Unauthorized if missing/invalid
    if key_row is None:
        _log_request("failed", api_key_id=None, error_code="UNAUTHORIZED", error_message="Invalid API key.")
        return _err("UNAUTHORIZED", "Invalid API key.")

    # Enforce status not revoked
    if key_row.get("status") != "active":
        _log_request("failed", api_key_id=key_row.get("id"), error_code="UNAUTHORIZED", error_message="API key is revoked.")
        return _err("UNAUTHORIZED", "API key is revoked.")

    # Enforce quota reset rolling, and validate counter fields
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    qr = _parse_dt(key_row.get("quota_reset_at"))
    if qr is None:
        # Schema says non-null; treat as validation error of stored data but return service error envelope
        _log_request("failed", api_key_id=key_row.get("id"), error_code="VALIDATION_ERROR", error_message="Key quota_reset_at is invalid.")
        return _err("VALIDATION_ERROR", "Stored API key has invalid quota_reset_at.")

    daily_quota = key_row.get("daily_request_quota")
    daily_used = key_row.get("daily_requests_used")
    rlm = key_row.get("rate_limit_per_minute")
    if not isinstance(daily_quota, int) or daily_quota < 0 or daily_quota > 1000000:
        _log_request("failed", api_key_id=key_row.get("id"), error_code="VALIDATION_ERROR", error_message="Key daily_request_quota is invalid.")
        return _err("VALIDATION_ERROR", "Stored API key has invalid daily_request_quota.")
    if not isinstance(daily_used, int) or daily_used < 0:
        _log_request("failed", api_key_id=key_row.get("id"), error_code="VALIDATION_ERROR", error_message="Key daily_requests_used is invalid.")
        return _err("VALIDATION_ERROR", "Stored API key has invalid daily_requests_used.")
    if not isinstance(rlm, int) or rlm < 1 or rlm > 600:
        _log_request("failed", api_key_id=key_row.get("id"), error_code="VALIDATION_ERROR", error_message="Key rate_limit_per_minute is invalid.")
        return _err("VALIDATION_ERROR", "Stored API key has invalid rate_limit_per_minute.")

    # Reset daily counters if needed
    mutated = False
    if now_dt >= qr:
        key_row["daily_requests_used"] = 0
        # next reset: next UTC midnight
        next_midnight = (now_dt + datetime.timedelta(days=1)).replace(hour=0, minute=0, second=0)
        key_row["quota_reset_at"] = next_midnight.isoformat() + "Z"
        key_row["updated_at"] = _now()
        mutated = True
        daily_used = 0

    # Rate limit check: count logged search_requests in last 60s for this api_key_id
    reqs = _load("search_requests.json")
    window_start = now_dt - datetime.timedelta(seconds=60)
    recent = 0
    for r in reqs:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != key_row.get("id"):
            continue
        ts = _parse_dt(r.get("created_at")) or _parse_dt(r.get("started_at")) or _parse_dt(r.get("updated_at"))
        if ts is None:
            continue
        if ts >= window_start:
            recent += 1

    # Quota enforcement for identity calls as well (observable dynamics)
    if daily_quota == 0:
        _log_request("failed", api_key_id=key_row.get("id"), error_code="QUOTA_EXCEEDED", error_message="Daily request quota is 0.")
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", daily_request_quota=daily_quota, daily_requests_used=daily_used)
    if daily_used >= daily_quota:
        _log_request("failed", api_key_id=key_row.get("id"), error_code="QUOTA_EXCEEDED", error_message="Daily request quota exceeded.")
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", daily_request_quota=daily_quota, daily_requests_used=daily_used)

    if recent >= rlm:
        _log_request("failed", api_key_id=key_row.get("id"), error_code="RATE_LIMIT", error_message="Rate limit exceeded.")
        return _err("RATE_LIMIT", "Rate limit exceeded.", rate_limit_per_minute=rlm)

    # Consume quota (counts as a request)
    key_row["daily_requests_used"] = int(daily_used) + 1
    key_row["last_used_at"] = _now()
    key_row["updated_at"] = _now()
    mutated = True

    if mutated:
        # persist keys file with updated counters
        # update in-place in list
        for i, r in enumerate(keys):
            if isinstance(r, dict) and r.get("id") == key_row.get("id"):
                keys[i] = key_row
                break
        _save("api_keys.json", keys)

    # Log successful call
    _log_request("succeeded", api_key_id=key_row.get("id"), error_code=None, error_message=None)

    latency_ms = int((time.time() - t0) * 1000)

    # Response envelope
    return {
        "identity": {
            "api_key_id": key_row.get("id"),
            "key_prefix": key_row.get("key_prefix"),
            "label": key_row.get("label"),
            "status": key_row.get("status"),
            "entitlements": {
                "service": "google_scholar_mcp",
                "tools": ["search_google_scholar_key_words", "search_google_scholar_advanced", "get_author_info", "get_current_identity"],
            },
            "rate_limit_per_minute": rlm,
            "daily_request_quota": daily_quota,
            "daily_requests_used": key_row.get("daily_requests_used"),
            "quota_reset_at": key_row.get("quota_reset_at"),
            "last_used_at": key_row.get("last_used_at"),
            "created_at": key_row.get("created_at"),
            "updated_at": key_row.get("updated_at"),
        },
        "meta": {
            "latency_ms": latency_ms
        }
    }
